import{_ as e,c as r,o,b0 as t}from"./chunks/framework.Becqh7-x.js";const l="/linux-dev-docs/assets/125ca74c77a81b60b48910afdb74e7ab.HQNMNdWD.png",g=JSON.parse('{"title":"LV005-交叉编译简介","description":null,"frontmatter":{"title":"LV005-交叉编译简介","date":"2026-01-06T09:18:33.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/dev-env/cros-compiling/126d2c6d3d392a9d3ca37791","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-01-06T09:18:33.681Z","fulluuid":"d3ca37791df74f9aa2d9af8295ced066","useduuid":"d3ca37791"}},"headers":[],"relativePath":"sdoc/dev-env/cros-compiling/126d2c6d3d392a9d3ca37791.md","filePath":"sdoc/05-开发环境/20-交叉编译/LV005-交叉编译简介.md","lastUpdated":1768604092000}'),i={name:"sdoc/dev-env/cros-compiling/126d2c6d3d392a9d3ca37791.md"};function n(c,a,d,s,p,u){return o(),r("div",null,[...a[0]||(a[0]=[t('<h1 id="lv005-交叉编译简介" tabindex="-1">LV005-交叉编译简介 <a class="header-anchor" href="#lv005-交叉编译简介" aria-label="Permalink to &quot;LV005-交叉编译简介&quot;">​</a></h1><h2 id="一、什么是交叉编译" tabindex="-1">一、什么是交叉编译？ <a class="header-anchor" href="#一、什么是交叉编译" aria-label="Permalink to &quot;一、什么是交叉编译？&quot;">​</a></h2><h3 id="_1-本地编译" tabindex="-1">1. 本地编译 <a class="header-anchor" href="#_1-本地编译" aria-label="Permalink to &quot;1. 本地编译&quot;">​</a></h3><p>在当前的 PC 下，x86 的 CPU 下，直接编译出来程序，可以运行的程序（或者库文件），其可以直接在当前的环境，即 x86 的 CPU 下，当前电脑中，运行。</p><p>此时的编译，可以叫做：本地编译，即在当前目标平台下，编译出来的程序，也只是放到当前平台下，就可以运行的。</p><h3 id="_2-交叉编译" tabindex="-1">2. 交叉编译 <a class="header-anchor" href="#_2-交叉编译" aria-label="Permalink to &quot;2. 交叉编译&quot;">​</a></h3><p>交叉编译是一种<strong>在一个平台上生成另一个体系结构不同的平台可执行代码</strong>的编译方式。</p><p>通常情况下，我们在一台计算机上编写和编译程序，<strong>编译后的可执行文件只能在与编译环境相同的硬件架构和操作系统上运行</strong>。但在一些特殊场景中，比如开发嵌入式系统、为不同架构的移动设备开发应用，或者针对特定的专用硬件平台进行软件开发时，就需要用到交叉编译技术。它允许开发者在自己常用的开发环境（如 x86 架构的 PC 上），编译出能够在其他不同架构（如 ARM 架构的嵌入式设备）上运行的代码。</p><p><img src="'+l+'" alt="img"></p><h3 id="_3-为什么要交叉编译" tabindex="-1">3. 为什么要交叉编译？ <a class="header-anchor" href="#_3-为什么要交叉编译" aria-label="Permalink to &quot;3. 为什么要交叉编译？&quot;">​</a></h3><p>主要原因是：<strong>嵌入式系统中的资源太少</strong>。</p><p>在进行嵌入式开发时，目标平台，即嵌入式开发板，比如是最大主频 200MHz 的 ARM 的 CPU，加上 32M 的 RAM，加上 1G 的 Nand Flash 等等。在如此相对比较紧张的硬件资源的前提下，还要运行了嵌入式 Linux 系统，是基本没法直接在嵌入式 Linux 下，去本地编译可以供开发板使用的程序。因为编译，开发，都需要相对比较多的 CPU，内存，硬盘等资源，而嵌入式开发上的那点资源，只够嵌入式（Linux）系统运行的，没太多剩余的资源，供本地编译使用，当然其实也不是不可以，对于一些处理性能很强的平台，可以编译一些比较小的程序，稍微大一点，编译速度就会很慢。</p><p>所以我们还是离不开 X86 电脑强大高效的桌面环境进行软件开发。但是这样有一个问题，X86、Arm、MIPS、RISC-V 这些芯片，它们的指令集是由不同的组织或者公司设计的，彼此并不兼容——Arm 和 MIPS 的 CPU 无法运行以 X86 的指令集编码的程序，反之亦然。所以我们要在 X86 的电脑上编译出能够在 Arm 上运行的程序，我们必须明确告诉编译器，编译生成的可执行文件需要以 Arm 指令集的标准编码。为了让这个流程变得简单，开发者们为不同的芯片开发了不同的编译器，比如针对 Arm 平台的 arm-linux-gcc，针对 mips 平台的 mips-linux-gnu-gcc，这些编译器都是基于 GCC 针对具体的架构指令集进行对应配置，所以它们在运行的时候就就会生成和该目标平台对应的可执行文件。</p><p><strong>那么交叉编译有哪些优势？</strong></p><ul><li><strong>方便开发</strong>：开发者可以在自己熟悉的开发环境中进行代码编写和调试，无需频繁切换到目标设备的环境，提高了开发效率。</li><li><strong>支持多种平台</strong>：能够轻松地为不同架构和操作系统的设备开发软件，扩大了软件的适用范围。比如，一个软件可以通过交叉编译同时支持 Windows、Linux、Android 等多种平台。</li><li><strong>提前测试</strong>：在开发主机上完成交叉编译后，可以在目标设备或模拟器上进行测试，及时发现和解决兼容性问题，减少在目标设备上直接开发和调试的时间成本。</li></ul><h2 id="二、交叉工具链" tabindex="-1">二、交叉工具链 <a class="header-anchor" href="#二、交叉工具链" aria-label="Permalink to &quot;二、交叉工具链&quot;">​</a></h2><h3 id="_1-工具和链" tabindex="-1">1. 工具和链 <a class="header-anchor" href="#_1-工具和链" aria-label="Permalink to &quot;1. 工具和链&quot;">​</a></h3><p>所谓的工具链，包含两部分：工具和链。</p><h4 id="_1-1-工具" tabindex="-1">1.1 工具 <a class="header-anchor" href="#_1-1-工具" aria-label="Permalink to &quot;1.1 工具&quot;">​</a></h4><p>工具：即 tool，目标是为了生成（可以运行的）程序或库文件。而为了达成此目标，内部的执行过程和逻辑主要包含了 <strong>编译</strong>、<strong>链接</strong>。</p><ul><li>编译</li></ul><p>编译所需要的工具就是编译器，在交叉编译中，称之为交叉编译器。例如 <code>Ubuntu</code> 中安装使用的 <code>GCC</code> 编译器是针对 <code>X86</code> 架构的。而我们现在要编译的是 <code>ARM</code> 架构的代码，所以我们需要一个在 <code>X86</code> 架构的 <code>PC</code> 上运行，可以编译 <code>ARM</code> 架构代码的 <code>GCC</code> 编译器，这个编译器就叫做 <strong>交叉编译器</strong>。</p><p>在这里，我使用的是开发板配套教程中 <code>Linaro</code> 出品的交叉编译器，而作为初学者的我，还是先跟教程走吧，哈哈。所以我使用的就是 <code>4.9</code> 版本的编译器啦。相关网址如下：</p><table><tbody><tr><td align="center" width="200"> linaro 官网 </td><td align="left"><a href="https://www.linaro.org/" target="_blank"> https://www.linaro.org/ <i class="fa fa-external-link-alt"></i></a></td></tr><tr><td align="center" width="200"> 4.9 版本交叉编译器 </td><td align="left"><a href="https://releases.linaro.org/components/toolchain/binaries/4.9-2017.01/arm-linux-gnueabihf/" target="_blank"> gcc-linaro-4.9.4-2017.01-x86_64_arm-linux-gnueabihf.tar.xz <i class="fa fa-external-link-alt"></i></a></td></tr></tbody></table><ul><li>链接</li></ul><p>链接的输入（对象）是（程序运行时所依赖的，或者某个库所依赖的另外一个）库（文件）。链接的输出（目标）是：程序的可执行文件，或者是可以被别人调用的完整的库文件。链接所需要的工具是：<strong>链接器</strong>，即 <code>ld</code></p><ul><li>还有一些其他工具</li></ul><p>实际上，上面所说的 ld，只是处理操作目标文件，二进制文件的最主要的一个工具。而和操作目标等文件相关的，还有其他很多工具的：as，objcopy，strip，ar 等等工具的。</p><p>所以，对此，GNU 官网，有一个 binutils，即 binary utils，二进制工具（包），集成了这些，和操作二进制相关的工具集合，叫做 binutils。所以，之后我们所见到的，常见的工具，就是刚才说的的著名的 GNU Binutils 了。</p><blockquote><p><a href="https://www.gnu.org/software/binutils/" target="_blank" rel="noreferrer">Binutils - GNU Project - Free Software Foundation</a></p></blockquote><h4 id="_1-2-链" tabindex="-1">1.2 链 <a class="header-anchor" href="#_1-2-链" aria-label="Permalink to &quot;1.2 链&quot;">​</a></h4><p>链，即链条，<code>chain</code>。之所以能称为链，说明不止一个东西，然后，按照对应的逻辑，串在一起，链在一起。而对应的，描述中涉及到的：</p><p>不止一个东西：指的是就是前面所说的那个工具，即和程序编译链接等相关的 gcc，binutils 等工具。</p><p>按照对应的逻辑：指的就是，按照程序本身编译链接的先后顺序，即先编译，后链接，再进行后期其他的处理等等，比如用 objcopy 去操作相应的目标文件等等。</p><p>如此的，将和程序编译链接等相关的 gcc，binutils 等工具按照先编译后链接等相关的编译程序的内在逻辑串起来，就成了我们所说的 <strong>工具链</strong>。</p><h3 id="_2-工具链种类" tabindex="-1">2. 工具链种类 <a class="header-anchor" href="#_2-工具链种类" aria-label="Permalink to &quot;2. 工具链种类&quot;">​</a></h3><p>GCC 的命名规则为：</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">arch</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [-vendor] [-os] [-(gnu)eabi]-gcc</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>比如 <code>arm-linux-gnueabi-gcc</code> ，<code>arm-none-eabi-gcc</code>， <code>aarch64-linux-gnu-gcc</code>，其中：</p><ul><li>带 <code>[]</code> 的是可选部分。</li><li>arch： 芯片架构，比如 32 位的 Arm 架构对应的 arch 为 arm，64 位的 Arm 架构对应的 arch 为 aarch64。</li><li>vendor ：工具链提供商，大部分工具链名字里面都没有包含这部分。</li><li>os ：编译出来的可执行文件(目标文件)针对的操作系统，比如 Linux。</li></ul><h3 id="_3-交叉工具链" tabindex="-1">3. 交叉工具链 <a class="header-anchor" href="#_3-交叉工具链" aria-label="Permalink to &quot;3. 交叉工具链&quot;">​</a></h3><blockquote><p>用于交叉编译的工具链，就叫做交叉工具链。即那些工具，即编译的 gcc，链接的 ld，以及相关的工具，用于交叉编译的，工具链，叫做交叉工具链。</p></blockquote><p>交叉工具链，很明显，是用来，交叉编译，跨平台的程序所用的。交叉工具链，和（本地）工具链类似，也是包含了很多的，对应的工具，交叉编译版本的 gcc，ld，as 等等。但是，由于其中最最主要的是用于编译的 gcc，所以，我们也常把：交叉工具链，简称为交叉编译器。</p><p>严格意义上来说，交叉编译器，只是指的是交叉编译版本的 gcc。但是实际上为了叫法上的方便，我们常说的交叉编译器，都是指的是交叉工具链。常说的交叉编译版本的 gcc，比如 arm-linux-gcc，实际上指代了，包含一系列交叉编译版本的交叉工具链（arm-linux-gcc，arm-linux-ld，arm-linux-as 等等）而此文中，后面，所说的，如无特殊指明，均用交叉编译器指代交叉工具链。</p><h3 id="_4-小结" tabindex="-1">4. 小结 <a class="header-anchor" href="#_4-小结" aria-label="Permalink to &quot;4. 小结&quot;">​</a></h3><p>其实我们可以看一个交叉编译工具链的内容都有哪些，比如这个<a href="https://releases.linaro.org/components/toolchain/binaries/4.9-2017.01/arm-linux-gnueabihf/gcc-linaro-4.9.4-2017.01-x86_64_arm-linux-gnueabihf.tar.xz" target="_blank" rel="noreferrer">gcc-linaro-4.9.4-2017.01-x86_64_arm-linux-gnueabihf.tar.xz</a> 我们下载后解压，这里就不展示了。解压后会发现，除了一些工具，还有大量的库和头文件。</p><p>其实<strong>交叉编译工具链是一个由编译器、连接器和解释器组成的综合开发环境</strong>，交叉编译工具链主要由 <code>binutils</code>、<code>gcc</code> 和 <code>glibc</code> 三个部分组成。有时出于减小 libc 库大小的考虑，也可以用别的 c 库来代替 <code>glibc</code>，例如：uClibc、dietlibc 和 newlib。</p><blockquote><p>参考资料：</p><p><a href="https://blog.csdn.net/Cappuccino_jay/article/details/125375029" target="_blank" rel="noreferrer">【交叉编译】什么是交叉编译，为何要有交叉编译？-CSDN 博客</a></p><p><a href="https://developer.huawei.com/consumer/cn/blog/topic/03178651684773161" target="_blank" rel="noreferrer">什么是交叉编译？ | 华为开发者联盟</a></p><p><a href="https://blog.csdn.net/qq_41854911/article/details/129975642" target="_blank" rel="noreferrer">一文搞懂交叉编译，Windows 和 Linux 的交叉编译_win10 配置树莓派交叉编译环境-CSDN 博客</a></p></blockquote>',48)])])}const b=e(i,[["render",n]]);export{g as __pageData,b as default};
